// Fixed-window request limiter, one counter per (tenant, region) pair, with a grace allowance.
export interface LimiterConfig {
  readonly limit: number;
  readonly windowMs: number;
  readonly grace: number;
}

export interface Decision {
  readonly allowed: boolean;
  readonly remaining: number;
  readonly grace: boolean;
}

interface WindowState {
  start: number;
  used: number;
  graceUsed: number;
  previousUsed: number;
}

function requireCount(name: string, value: number, min: number): void {
  if (!Number.isInteger(value) || value < min) {
    throw new RangeError(`${name} must be an integer >= ${min}`);
  }
}

/** Escapes the separator, so ("a:b", "c") and ("a", "b:c") get different keys. */
function pairKey(tenant: string, region: string): string {
  const escape = (part: string) => part.replaceAll("\\", "\\\\").replaceAll(":", "\\:");
  return `${escape(tenant)}:${escape(region)}`;
}

function windowStart(now: number, windowMs: number): number {
  return Math.floor(now / windowMs) * windowMs;
}

export function createLimiter(config: LimiterConfig) {
  requireCount("limit", config.limit, 1);
  requireCount("windowMs", config.windowMs, 1);
  requireCount("grace", config.grace, 0);
  const windows = new Map<string, WindowState>();
  return {
    check(tenant: string, region: string, now: number): Decision {
      const key = pairKey(tenant, region);
      const start = windowStart(now, config.windowMs);
      let state = windows.get(key);
      if (state === undefined || state.start !== start) {
        const previousUsed = state !== undefined && state.start + config.windowMs === start ? state.used : 0;
        state = { start, used: 0, graceUsed: 0, previousUsed };
        windows.set(key, state);
      }
      if (state.used < config.limit) {
        state.used += 1;
        return { allowed: true, remaining: config.limit - state.used, grace: false };
      }
      const graceOpen = state.previousUsed * 2 <= config.limit;
      if (graceOpen && state.graceUsed < config.grace) {
        state.graceUsed += 1;
        return { allowed: true, remaining: 0, grace: true };
      }
      return { allowed: false, remaining: 0, grace: false };
    },
  };
}
